using System;
using System.Text.Json;
using System.Text.Json.Serialization.Metadata;

// 1) Strongly-typed metadata via the generic GetTypeInfo<T>()
var options = new JsonSerializerOptions
{
    TypeInfoResolver = JsonSerializerOptions.Default.TypeInfoResolver
};

JsonTypeInfo<int[]> arrayInfo = (JsonTypeInfo<int[]>)options.GetTypeInfo(typeof(int[]));
Console.WriteLine($"1. GetTypeInfo for int[]: Kind={arrayInfo.Kind}, Type={arrayInfo.Type}");

// 2) Probe without throwing via TryGetTypeInfo
//    Succeeds for int[] (resolver knows about it):
if (options.TryGetTypeInfo(typeof(int[]), out JsonTypeInfo? found))
{
    Console.WriteLine($"2a. TryGetTypeInfo(int[]) succeeded: Kind={found!.Kind}");
}

//    Use a resolver that knows about nothing → TryGetTypeInfo returns false
var limited = new JsonSerializerOptions
{
    TypeInfoResolver = JsonTypeInfoResolver.Combine()   // empty composite
};

if (!limited.TryGetTypeInfo(typeof(int[]), out _))
{
    Console.WriteLine("2b. TryGetTypeInfo(int[]) on empty resolver → false (no exception)");
}
EOF

